Implemented in `middleware.ts:1`:

```ts
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

export function middleware(request: NextRequest) {
  console.log(request.nextUrl.pathname);

  const response = NextResponse.next();
  response.headers.set("X-Request-Id", crypto.randomUUID());

  return response;
}

export const config = {
  matcher: "/:path*",
};
```

This logs each request pathname and adds a unique `X-Request-Id` header to responses for all matched paths.  
I also ran `npm run build` to verify it compiles successfully. Next.js 16 shows a deprecation warning that `middleware.ts` is being replaced by `proxy.ts`, but this implementation works.
